window.CERT_DATA=window.CERT_DATA||{};window.CERT_DATA['adsp-34']={"round":34,"cert":"adsp","questions":[{"id":"62086","number":1,"category":"데이터 이해","type":"choice","subject":"다음 중 빅데이터 시대의 위기 요인과 사례가 아닌 것은","choices":[{"n":1,"html":"사생활 침해- 개인정보를 동의 없이 수집하여 맞춤형 광고 제작"},{"n":2,"html":"책임 원칙 훼손- 특정 집단에 소속되어 있다는 이유로 부당한 직원 해고"},{"n":3,"html":"책임 원칙 훼손- 특정성향의 직원에 대한 채용 거부"},{"n":4,"html":"데이터 오용- 상업적 목적으로 데이터 크롤링 하여 개인정보 수집"}],"answer":[4],"explain":{"ai":["<p>빅데이터 시대의 위기 요인은 개인의 사생활 침해와 책임 원칙의 훼손 등이 있다. 책임 원칙 훼손은 특정 집단이나 성향에 따라 부당한 대우를 받는 경우를 말한다. </p>\n<p>에도 특정 집단에 소속되어 있다는 이유로 부당한 직원 해고나 특정 성향의 직원에 대한 채용 거부가 있다. 이 경우 특정 개인이나 집단에 대한 불이익을 의미한다.</p>\n<p>반면 4번은 데이터 오용으로서 데이터 크롤링을 통해 개인정보 수집은 데이터 침해와 관련이 있다. 그러나 이는 특정 개인이나 집단에 대한 부당한 대우가 아니라 개인정보를 보호하지 못한 경우로 볼 수 있다. </p>\n<p>따라서 빅데이터 시대의 위기 요인과 사례가 아닌 것은 데이터 오용- 상업적 목적으로 데이터 크롤링하여 개인정보 수집이다.</p>"]},"rate":53,"rateN":4876},{"id":"62087","number":2,"category":"데이터 이해","type":"choice","subject":"다음 중 빅데이터 분석의 특징에 대한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"데이터가 방대하다고 무조건 더 좋은 가치를 창출하는 것은 아니다."},{"n":2,"html":"데이터 크기가 커질수록 더 많은 분석을 수행하는 것이 경쟁 우위 확보의 원천이다."},{"n":3,"html":"분석적 방법과 성과에 대한 이해 부족은 빅데이터 과제에 대한 걸림돌이다"},{"n":4,"html":"비즈니스의 핵심에 더욱 객관적이고 통찰력 있는 데이터를 추출하는 것이 중요하다."}],"answer":[2],"explain":{"ai":["<p>빅데이터 분석은 방대한 양의 데이터를 처리하여 가치를 창출하는 것이 목적이다.但是 데이터가 많다고 해서 항상 더好的 가치를 창출하는 것은 아니다. 데이터의 품질과 관련성, 분석 방법이 중요하기 때문이다. 따라서 데이터 크기가 커질수록 더 많은 분석을 수행하는 것이 경쟁 우위 확보의 원천이라는 설명은 옳지 않다. 빅데이터 분석의 특징은 데이터의 다양성과 복잡성, 속도 등이다. 또한 분석적 방법과 성과에 대한 이해 부족은 빅데이터 과제에 대한 걸림돌이다. 비즈니스의 핵심에 더욱 객관적이고 통찰력 있는 데이터를 추출하는 것이 중요하다. 따라서 정답은 2번이다.</p>"]},"rate":73,"rateN":3680},{"id":"62088","number":3,"category":"데이터 이해","type":"choice","subject":"다음 중 빅데이터의 가치 측정이 어려운 이유가 아닌 것은?","choices":[{"n":1,"html":"데이터 재사용이 일반화되어 특정 데이터를 언제 누가 사용했는지 알기 힘들다."},{"n":2,"html":"빅데이터는 기존에 존재하지 않던 가치를 창출한다."},{"n":3,"html":"빅데이터 전문 인력의 증가로 다양한 곳에서 빅데이터가 활용되고 있다."},{"n":4,"html":"데이터 분석 기술의 발전으로 과거에는 분석할 수 없었던 데이터도 분석할 수 있게 됐다."}],"answer":[3],"explain":{"ai":["<p>빅데이터의 가치 측정은 여러 가지 이유로 어려울 수 있다. 데이터 재사용이 일반화되어 특정 데이터를 언제 누가 사용했는지 알기 힘들기 때문이다. 또한 빅데이터는 기존에 존재하지 않던 새롭고 다양한 가치를 창출하기 때문에 이를 측정하기 어렵다. 또 과거에는 분석할 수 없었던 데이터도 분석할 수 있게 됨에 따라 가치 측정이 복잡해질 수 있다. 하지만 빅데이터 전문 인력의 증가로 다양한 곳에서 빅데이터가 활용되고 있다는 것은 가치 측정의 어려움과 직접적으로 관련이 없다. 즉, 전문 인력의 증가로 빅데이터의 활용이 늘어난다는 것은 빅데이터의 가치가 높아진다는 것을 의미하므로 빅데이터의 가치 측정이 어려운 이유가 아니다.</p>"]},"rate":59,"rateN":4205},{"id":"62089","number":4,"category":"데이터 이해","type":"choice","subject":"다음 중 분석 과제 정의서에 필수적으로 포함되어야 할 항목이 아닌 것은?","choices":[{"n":1,"html":"필요 소스 데이터/ 분석 정의"},{"n":2,"html":"데이터 입수 난이도"},{"n":3,"html":"분석 수행주기"},{"n":4,"html":"상세 분석 알고리즘"}],"answer":[4],"explain":{"ai":["<p>정답은 4번입니다. 분석 과제 정의서는 프로젝트의 명확한 이해와 실행 계획을 위한 핵심 요소들을 포괄해야 합니다. </p>\n<p>1번의 '필요 소스 데이터/ 분석 정의'는 분석의 기반이 되는 데이터와 목적을 명확히 하므로 필수적입니다.\n2번의 '데이터 입수 난이도'는 프로젝트 계획 단계에서 고려해야 할 중요한 요소로, 리소스와 시간을 예측하는 데 필요합니다.\n3번의 '분석 수행주기'는 정기적인 분석의 경우 수행 일정을 정의하여 관리의 효율성을 높입니다.</p>\n<p>반면, 4번의 '상세 분석 알고리즘'은 구체적인 분석 방법론이며, 일반적인 정의서에서는 프로젝트의 큰 그림과 목표를 설정하는 데 초점을 맞춥니다. 알고리즘의 세부사항은 실제 분석 수행 단계나 기술 사양서에서 더 자세히 다루어지곤 합니다. 따라서 분석 과제 정의서의 필수 항목 중 하나로 보기는 어렵습니다.</p>"]},"rate":50,"rateN":4695},{"id":"62090","number":5,"category":"데이터 이해","type":"choice","subject":"다음 중 데이터 사이언스에 대한 설명으로 올바르지  않은 것은?","choices":[{"n":1,"html":"데이터에서 의미 있는 정보를 찾는 문학이다."},{"n":2,"html":"주로 분석 정확성에 초점을 맞춰 수행한다."},{"n":3,"html":"정형 데이터 뿐만 아니라 다양한 유형의 데이터를 활용한다."},{"n":4,"html":"기존의 통계학과는 달리 총체적 접근법을 사용한다."}],"answer":[2],"explain":{"ai":["<p>올바르지 않은 설명은 2번입니다. 데이터 사이언스는 단순히 분석의 정확성에만 초점을 맞추는 것이 아니라, 데이터 탐색, 모델링, 해석, 그리고 결과의 실용적 적용까지 포괄하는 다층적 접근을 취합니다. 정확성은 중요한 요소이지만, 데이터 사이언스는 효율성, 모델의 해석 가능성, 그리고 비즈니스 또는 사회적 맥락에서의 영향력 등 다양한 측면을 고려합니다. 따라서, 정확성만을 강조하는 설명은 데이터 사이언스의 포괄적인 성격을 왜곡합니다.</p>"]},"rate":74,"rateN":3568},{"id":"62091","number":6,"category":"데이터 이해","type":"choice","subject":"DBMS에 대한 설명이 옳지 않은 것은?","choices":[{"n":1,"html":"데이터베이스 관리로 모든 데이터 문제를 해결 할 수 있다."},{"n":2,"html":"우리나라에서 일반적으로 많이 사용되는 데이터베이스 관리 시스템은 관계형 DBMS다."},{"n":3,"html":"사용자들이 동시에 트랜잭션 하는 경우에도 즉각적으로 결과값을 확인 할 수 있다."},{"n":4,"html":"계정을 가진 모든 사용자가 접근이 가능하다."}],"answer":[1],"explain":{"ai":["<p>DBMS는 데이터를 효율적으로 관리하고 저장하고 조회할 수 있게 해주는 시스템이다. 하지만 모든 데이터 문제를 해결할 수 있는 것은 아니다. 예를 들어 데이터의 질이나 일관성 등은 DBMS만으로 해결할 수 없다. </p>\n<p>일반적으로 우리나라에서 많이 사용되는 데이터베이스 관리 시스템은 관계형 DBMS이다. 사용자들이 동시에 트랜잭션을 하는 경우에도 즉각적으로 결과값을 확인할 수 있는 것은 TRUE이다. </p>\n<p>계정을 가진 모든 사용자가 접근이 가능하다라는 것은 FALSE이다. DBMS에서는 계정별로 접근할 수 있는 데이터나 수행할 수 있는 작업이 다르기 때문이다. </p>\n<p>따라서 DBMS에 대한 설명이 옳지 않은 것은 모든 데이터 문제를 해결할 수 있다라는 것이다.</p>"]},"rate":74,"rateN":3596},{"id":"62092","number":7,"category":"데이터 이해","type":"choice","subject":"다음 중 데이터베이스 활용 관련 내용으로 틀린 것은?","choices":[{"n":1,"html":"데이터 웨어하우스는 저장 수단이고 데이터 마트는 소비자에게 제공되는 수단이다."},{"n":2,"html":"데이터 마트는 특정 조직이나 부서의 사람들 뿐만 아니라 모든 사람이 사용할 수 있다."},{"n":3,"html":"데이터 마트는 데이터 웨어하우스로 부터 특정 주제, 부서 중심으로 구축된 소규모 단일 주제 데이터 웨어하우스이다."},{"n":4,"html":"데이터 웨어하우스는 다양한 운영 시스템에서 추출, 변환, 통합되고 요약된 데이터베이스이다."}],"answer":[2],"explain":{"ai":["<p>데이터베이스 활용 관련 내용 중 틀린 것은 데이터 마트가 모든 사람이 사용할 수 있다라는 것이다. 데이터 마트는 특정 조직이나 부서의 사람들이 사용하기 위한 목적으로 만들어진 소규모 데이터 웨어하우스로 모든 사람이 사용할 수 있는 것이 아니다. 데이터 마트는 데이터 웨어하우스에서 특정 주제나 부서 중심으로 구축된 것으로 주로 해당 부서나 조직의 업무를 지원하기 위해 설계된다. 따라서 모든 người가 사용할 수 있는 것이 아니며, 주로 특정 부서나 조직의 사람들만 사용한다.</p>"]},"rate":65,"rateN":3816},{"id":"62093","number":8,"category":"데이터 이해","type":"choice","subject":"빅데이터 전략 도출을 위한 가치기반 분석에 대한 내용으로 옳지 않은 것은?","choices":[{"n":1,"html":"일차적 분석만으로 해당 부서 및 업무에 효과가 없다."},{"n":2,"html":"빅데이터는 가치 창출이 가능해야 하고, 그 시점이 빠를수록 좋다."},{"n":3,"html":"빅데이터의 걸림돌은 분석적 방법과 성과에 대한 이해부족이다."},{"n":4,"html":"기업의 핵심 가치와 관련해 전략적 통찰력을 가져다 주는 데이터 분석을 내재화 하는 것이 어렵다."}],"answer":[1],"explain":{"ai":["<p>정답은 1번입니다. </p>\n<p>빅데이터 전략 도출을 위한 가치기반 분석에서는 일차적 분석만으로도 특정 부서나 업무에 대한 효과를 파악할 수 있는 경우가 많습니다. 다만, 깊이 있는 통찰력을 얻기 위해서는 추가적인 분석이 필요할 수 있습니다. 따라서 \"일차적 분석만으로 해당 부서 및 업무에 효과가 없다\"는 주장은 정확하지 않습니다. </p>\n<p>다른 보기들은 다음과 같이 타당합니다:</p>\n<ul>\n<li>2번: 빅데이터의 핵심은 신속한 가치 창출에 있으며, 빠른 시점에 이를 실현하는 것이 중요합니다.</li>\n<li>3번: 빅데이터 활용의 주요 장애물 중 하나는 분석 기법과 그로 인한 성과에 대한 이해 부족입니다.</li>\n<li>4번: 기업의 핵심 가치와 연계된 전략적 통찰력을 데이터 분석을 통해 내재화하는 과정은 복잡하고 어려울 수 있습니다.</li>\n</ul>"]},"rate":60,"rateN":3911},{"id":"62094","number":9,"category":"데이터 이해","type":"short","subject":"데이터의 가공 및 상관관계 간 이해를 통해 패턴을 인식하고 그 의미를 부여한 데이터를 무엇이라고 하는가?","shortAnswer":"정보","explain":{"ai":["<p>데이터의 가공 및 상관관계 간 이해를 통해 패턴을 인식하고 그 의미를 부여한 데이터를 정보라고 합니다. 정보는 데이터를 분석하고 가공하여 의미를 부여한 결과물입니다. 즉, 데이터는 단순한 사실이나 수치지만 정보는 그 데이터를 기반으로 해석하고 분석하여 도출된 유의미한 내용입니다. 이러한 정보는 의사결정이나 문제解决 등을 위해 사용됩니다. 정보는 데이터를 분석하고 상관관계를 파악하여 패턴을 인식하고 의미를 부여함으로써 만들어집니다. 따라서 데이터의 가공 및 분석을 통해 의미를 추출해 내는 것이 정보입니다.</p>"]}},{"id":"62095","number":10,"category":"데이터 이해","type":"short","subject":"인터넷으로 연결된 기계마다 통신 장치를 갖추고 있는 환경에서 사람 또는 기계끼리 자동으로 통신하는 기술로써 사물과 사람, 사물과 사물 간의 정보를 상호 소통하는 방식을 무엇이라 하는가?","shortAnswer":"IoT","explain":{"ai":["<p>인터넷으로 연결된 기계마다 통신 장치를 갖추고 있는 환경에서 사람 또는 기계끼리 자동으로 통신하는 기술로써 사물과 사람, 사물과 사물 간의 정보를 상호 소통하는 방식은 IoT라고 합니다. \nIoT는 사물인터넷을 의미하며 인터넷에 연결된 모든 기기나 사물이 데이터를 서로 교환하고 상호 작용할 수 있는 기술입니다. \n이러한 기술은 다양한 종류의 센서와 장치가互いに 연결되어 데이터를 수집하고 전송하며 자동으로 통신하는 것을 가능하게 합니다. \n예를 들어 스마트 홈 시스템이나 사물인터넷 기반의 산업 자동화 시스템에서 사용됩니다. \n이러한 기술은 людей의生活을更加 편리하고 효율적으로 만드는 데 기여합니다.</p>"]}},{"id":"62096","number":11,"category":"데이터 분석 기획","type":"choice","subject":"데이터 분석 과제에서 분석 프로젝트 관리에 대한 설명 중 틀린 것은?","choices":[{"n":1,"html":"분석 과제는 분석 전문가의 상상력을 요구하므로 일정을 제한하는 일정 계획은 적절하지 못하다."},{"n":2,"html":"분석 과제는 적용되는 알고리즘에 따라 범위가 변할 수 있어 범위 관리가 중요하다."},{"n":3,"html":"분석 과제에서 다양한 데이터를 확보하는 경우가 있어 조달관리 또한 중요하다."},{"n":4,"html":"분석 과제에는 많은 위험이 있어 사전에 위험을 식별하고 대응 방안을 수립해야 한다."}],"answer":[1],"explain":{"ai":["<p>정답은 1번입니다. 분석 프로젝트에서도 명확한 일정 계획은 필수적입니다. 상상력은 창의적인 접근에 중요하지만, 프로젝트의 성공을 위해서는 현실적인 시간 관리와 목표 설정이 필요합니다. 일정을 제한함으로써 팀원 간의 책임 분배와 프로젝트의 전체적인 진행 상황을 효과적으로 추적하고 관리할 수 있습니다. 따라서 분석 전문가의 작업이라도 구조화된 일정 계획 없이 진행되는 것은 적절하지 않으며, 이는 프로젝트의 효율성과 완료 가능성에 부정적인 영향을 미칠 수 있습니다. 다른 보기들은 각각 범위 관리, 데이터 조달, 위험 관리의 중요성을 적절히 강조하고 있어 정확합니다.</p>"]},"rate":88,"rateN":2840},{"id":"62097","number":12,"category":"데이터 분석 기획","type":"choice","subject":"분석 준비도의 분석 업무파악 영역이 아닌 것은?","choices":[{"n":1,"html":"업무별 적합한 분석기법 사용"},{"n":2,"html":"최적화 분석 업무"},{"n":3,"html":"발생한 사실 분석 업무"},{"n":4,"html":"예측 분석 업무"}],"answer":[1],"explain":{"ai":["<p>분석 준비도는 데이터 분석의 사전 준비 단계를 뜻합니다. 분석 업무 파악은 분석의 목적과 범위 등을 명확히 하는 것을 의미합니다. \n분석 준비도의 분석 업무 파악 영역이 아닌 것은 업무별 적합한 분석기법 사용입니다. 분석 준비도에서 분석 기법을 선택하는 것은 분석 업무 수행 단계에 해당하므로 분석 업무 파악과는 다릅니다. \n증거나 사실을 분석해서 혹은 예측해서 최적화 할 수 있습니다. 발생한 사실을 분석하거나 예측 분석도 하며 그 정보로 업무를 최적화 하기도 합니다. 따라서 발생한 사실 분석 업무나 예측 분석 업무, 최적화 분석 업무는 모두 분석 업무 파악에 속하는 영역입니다.</p>"]},"rate":43,"rateN":4930},{"id":"62098","number":13,"category":"데이터 분석 기획","type":"choice","subject":"분석 마스터 플랜에 대한 내용으로 틀린 것은?","choices":[{"n":1,"html":"전체 과정을 순환적이고 반복적인 단계로 작성한다."},{"n":2,"html":"분석 과제의 적용 범위 및 방식에 대해서도 종합적으로 고려하여 결정한다."},{"n":3,"html":"일반적인 IT 프로젝트의 우선순위로는 전략적 중요도와 실행 용이성이 있다."},{"n":4,"html":"분석 마스터 플랜의 순서는 중장기 마스터 플랜 수립- 단기적인 세부 이행계획 수립- 과제 별 우선순위 설정 순서이다."}],"answer":[1],"explain":{"ai":["<p>분석 마스터 플랜은 데이터 분석 프로젝트의 전반적인 방향과 우선순위를 정의하는 중요한 문서다. इसम에는 전체적인 비전과 목표, 분석 대상과 적용 범위, 구현 방식과 우선순위 등이 포함된다. 일반적인 IT 프로젝트의 우선순위는 전략적 중요도와 실행 용이성에 의해 결정된다. 분석 마스터 플랜의 순서는 중장기 마스터 플랜 수립, 단기적인 세부 이행 계획 수립, 과제 별 우선순위 설정 순서로 진행된다. 하지만 분석 마스터 플랜은 순환적이고 반복적인 단계로 작성하는 것이 아니라, 심사숙고한 계획을 수립하는 것이 중요하다. 따라서 1번이 틀린 내용이다.</p>"]},"rate":50,"rateN":4144},{"id":"62099","number":14,"category":"데이터 분석 기획","type":"choice","subject":"하향식 접근 방법에 대한 설명으로 옳지 않은 것은?","choices":[{"n":1,"html":"빠짐없이 문제를 도출하고 식별하는 것이 중요하다."},{"n":2,"html":"문제를 해결함으로써 발생하는 가치에 중점을 두는 것이 중요하다."},{"n":3,"html":"비즈니스 모델 캔버스를 문제 탐색 도구로 활용한다."},{"n":4,"html":"분석 유스케이스 활용보다는 새로운 문제 탐색이 우선한다."}],"answer":[4],"explain":{"ai":["<p>하향식 접근 방법은 전체적인 비즈니스 목표나 전략을 먼저 설정하고, 이를 달성하기 위해 필요한 문제점이나 기회를 식별하는 방법이다. 이는 문제를 해결함으로써 발생하는 가치를 중점으로 두기 때문에, 비즈니스 모델 캔버스와 같은 도구를 활용하여 문제를 탐색하는 것이 중요하다. 또한 분석 유스케이스를 활용하여 문제를 해결하는 것이 중요하므로, 새로운 문제 탐색보다는 분석 유스케이스 활용이 우선시 되어야 한다. 따라서 4번은 하향식 접근 방법에 대한 설명으로 옳지 않다.</p>"]},"rate":73,"rateN":3331},{"id":"62100","number":15,"category":"데이터 분석 기획","type":"choice","subject":"CRISP-DM에 대한 내용으로 올바른 것은?","extra":"<pre class=\"contents\">가. 데이터 이해에서 데이터 준비 단계로 갈 수 있다.\r\n나. 모델링 단계에서 학습용/테스트용 데이터를 사용해 과소 적합을 확인한다.\r\n다. 비즈니스 이해, 데이터 이해 간 피드백이 가능하다.\r\n라. 평가에서 적합하면 바로 프로젝트 투입이 가능하다.</pre>","choices":[{"n":1,"html":"가, 라"},{"n":2,"html":"가, 나, 라"},{"n":3,"html":"가, 나, 다"},{"n":4,"html":"나, 라"}],"answer":[3],"explain":{"ai":["<p>CRISP-DM은 데이터 마이닝 프로젝트를 체계적으로 관리하기 위한 방법론입니다. 여러 단계로 이루어져 있으며, 데이터 이해와 데이터 준비 단계를 포함하여 비즈니스 이해와 모델링 등의 단계가 있으며 각 단계 간 피드백이 가능합니다. </p>\n<p>데이터 이해 단계에서는 데이터의 특성을 파악하고, 데이터 준비 단계에서는 데이터를 클렌징하고 변환하여 분석에 사용할 수 있도록 합니다. 모델링 단계에서 과소 적합을 확인하기 위해 학습용과 테스트용 데이터를 사용합니다. </p>\n<p>비즈니스 이해와 데이터 이해 간 피드백이 가능하여 프로젝트의 목적과 데이터의 상태를 고려하여 계획을 조정할 수 있습니다. </p>\n<p>그러나 평가 단계에서 적합하면 바로 프로젝트에 투입할 수 있는 것은 아니며, 추가적인 검토와 테스트가 필요할 수 있습니다. </p>\n<p>따라서 CRISP-DM의 특성에 맞는 내용은 가, 나, 다입니다.</p>"]},"rate":59,"rateN":3829},{"id":"62101","number":16,"category":"데이터 분석 기획","type":"choice","subject":"빅데이터 분석 방법론 시스템 구현 단계에 해당하는 것으로 짝지어진 것은?","choices":[{"n":1,"html":"설계 및 구현, 시스템 테스트 및 운영"},{"n":2,"html":"모델링, 모델 평가 및 검증"},{"n":3,"html":"설계 및 구현, 프로젝트 평가 보고"},{"n":4,"html":"모델링, 데이터 스토어 설계"}],"answer":[1],"explain":{"ai":["<p>빅데이터 분석 방법론에서 시스템 구현 단계는 실제 시스템을 구축하고 그 기능을 확인하는 과정을 포함한다.</p>\n<p>1번 옵션은 \"설계 및 구현\"과 \"시스템 테스트 및 운영\"으로 구성되어 있어, 이는 분석 시스템을 실제로 만들어 내고 그 안정성과 기능을 검증한 뒤에 운영으로 이어가는 정확한 순서를 반영한다.</p>\n<p>2번은 모델링과 검증에 초점을 맞추고 있어 주로 분석 모델 개발과 평가 단계에 해당한다.</p>\n<p>3번은 설계 및 구현 이후에 프로젝트 평가 보고를 포함하고 있지만, 시스템 구현 단계보다는 프로젝트 마무리 단계에 더 가깝다.</p>\n<p>4번은 모델링과 데이터 저장소 설계를 묶어 놓았는데, 이는 분석 모델 개발과 데이터 관리 측면을 다루고 있어 구현 단계보다는 초기 설계 단계에 더 가깝다.</p>\n<p>따라서, 빅데이터 분석의 구체적인 시스템 구현 단계를 정확히 나타내는 것은 1번이 정답이다.</p>"]},"rate":68,"rateN":3461},{"id":"62102","number":17,"category":"데이터 분석 기획","type":"choice","subject":"데이터 분석 방법론 분석 기획 시 고려사항으로 틀린 내용은?","choices":[{"n":1,"html":"타당성 단계에서 데이터 및 기술적 타당성은 복잡한 문제이기 때문에 다양한 사람들의 의견을 들어보는 것이 중요하다."},{"n":2,"html":"장애요소 사전 계획 수립이 필요하다."},{"n":3,"html":"분석을 위한 데이터 확보 및 데이터 유형에 대한 분석이 선행되어야 한다."},{"n":4,"html":"유사 분석 시나리오 및 솔루션이 있다면 이를 최대한 활용해야 한다."}],"answer":[1],"explain":{"ai":["<p>정답은 1번입니다. 타당성 단계에서 데이터 및 기술적 타당성은 중요하지만, 다양한 사람들의 의견을 듣는 것이 핵심이 아니라 체계적인 평가와 분석이 필요합니다. 의견 수렴은 의사결정 과정에서 도움이 될 수 있지만, 타당성 분석은 주로 객관적 기준과 기술적 적합성에 초점을 맞춥니다. 그 외 2번의 장애요소 사전 계획, 3번의 데이터 확보와 유형 분석, 4번의 유사 사례 활용은 모두 분석 기획 시 필수적인 고려사항입니다.</p>"]},"rate":60,"rateN":3751},{"id":"62103","number":18,"category":"데이터 분석 기획","type":"choice","subject":"분석 프로젝트의 관리 방안에 대한 설명 중 적절하지 않은 것은?","choices":[{"n":1,"html":"분석의 활용적인 측면에서는 정확도가 중요하며, 안정적인 측면에서는 정밀도가 중요하다."},{"n":2,"html":"모델을 지속적으로 반복했을 때 편차의 수준을 정확도라고 한다."},{"n":3,"html":"난이도에 우선 순위 기준을 놓으면 시급성 높고 난이도 쉬운 과제가 가장 먼저 수행되어야 한다."},{"n":4,"html":"시급성이 높고 난이도가 높은 분석 과제는 경영진에 의해 조정 가능하다."}],"answer":[2],"explain":{"ai":["<p>적절하지 않은 관리 방안은 모델을 반복했을 때 편차의 수준을 정확도라고 설명하는 것임. 이는 실제로 정확도는 모델의 예측 값과 실제 값의 차이를 의미하며, 정밀도는 모델의 예측 값들 사이의 편차를 의미함. 모델이 지속적으로 반복했을 때의 편차 수준은 정밀도에 해당함. 따라서 관리 방안 중 설명이 부정확한 것은 2번임.</p>"]},"rate":55,"rateN":3985},{"id":"62104","number":19,"category":"데이터 분석 기획","type":"short","subject":"식별된 비즈니스 문제를 데이터의 문제로 변환하여 정의하는 단계는 무엇인가?","shortAnswer":"문제 정의","explain":{"ai":["<p>비즈니스 문제를 데이터의 문제로 변환하여 정의하는 단계는 문제 정의 단계야. 이 단계에서는 비즈니스 문제를 명확하게 이해하고 데이터 분석을 통해서 해결할 수 있는 문제로 명확히 정의해야 해. 비즈니스 문제를 데이터 관점에서 바라보는 단계라 생각하면 돼. 이때 데이터 분석의 목적과 Scope를 정의하는 것도 중요한 작업이야.</p>"]}},{"id":"62105","number":20,"category":"데이터 분석 기획","type":"short","subject":"다음 빈칸에 들어갈 말은?","extra":"<pre class=\"contents\">전사 차원의 모든 데이터에 대하여 정책 및 지침, 표준화, 운영조직 및 책임 등의 표준화된 관리체계를 수립하고 운영을 위한 프레임워크 및 저장소(Repository)를 구축하는 것을 말한다. 마스터 데이터, 메타 데이터, 데이터 사전은 (   )의 중요한 관리 대상이다.</pre>","shortAnswer":"데이터 거버넌스","explain":{"ai":["<p>데이터 거버넌스는 전사 차원의 모든 데이터에 대한 표준화된 관리체계를 의미한다. 이는 데이터의 정책, 지침, 표준화, 운영조직 및 책임 등을 체계적으로 관리하는 것을 말한다. 데이터 거버넌스에는 마스터 데이터, 메타 데이터, 데이터 사전이 중요한 관리 대상으로 포함된다. 이러한 관리를 통해 데이터의 일관성과 신뢰성을 확보하고, 데이터에 대한 적절한 사용과 보안을 유지할 수 있다. 따라서 마스터 데이터, 메타 데이터, 데이터 사전은 데이터 거버넌스의 중요한 구성 요소이다.</p>"]}},{"id":"62106","number":21,"category":"데이터 분석","type":"choice","subject":"boxplot에 대한 설명으로 적절하지 않은 것은?","choices":[{"n":1,"html":"박스플롯의 가운데 중심선은 중앙값을 의미한다."},{"n":2,"html":"다섯개 숫자(최소값, 최대값, 중앙값, 제1사분위수, 제3사분위수)를 확인할 수 있다."},{"n":3,"html":"데이터의 전체적인 분포를 확인할 수 있다."},{"n":4,"html":"이상치를 확인하는 데는 부적절하다."}],"answer":[4],"explain":{"ai":["<p>박스플롯은 Hình_quadro를 통해 데이터 분포를 시각적으로 표현하는 그래프이다. 박스플лот에서 가운데 중심선은 중앙값을 나타내고 제1사분위수와 제3사분위수를 통해 데이터의 phân포를 알 수 있다. 또한 박스플롯에서는 데이터의 최소값과 최대값을 확인할 수 있고, 박스플롯의 外側에 있는 값은 이상치로 판단된다. 즉 박스플롯은 데이터의 분포를 확인하고 이상치를 확인하는 데 적절하다. 따라서 이상치를 확인하는 데에는 부적절하다고 하는 4번이 적절하지 않은 설명이다.</p>"]},"rate":81,"rateN":2605},{"id":"62107","number":23,"category":"데이터 분석","type":"choice","subject":"카달로그 배열, 교차 판매 등의 마케팅을 계획할 때 적절한 데이터 마이닝 기법은?","choices":[{"n":1,"html":"연관규칙 학습"},{"n":2,"html":"군집 분석"},{"n":3,"html":"회귀 분석"},{"n":4,"html":"분류 분석"}],"answer":[1],"explain":{"ai":["<p>카달로그 배열, 교차 판매 등의 마케팅 계획을 수립할 때는 적절한 데이터 마이닝 기법이 필요하다. 이 경우에 가장 적절한 기법은 연관규칙 학습이다. 연관규칙 학습은 데이터 간의 연관성을 분석하여 특정한 규칙이나 패턴을 발견하는 데 사용된다. 예를 들어, 어떤 고객이 특정 상품을 구매할 경우 다른 어떤 상품을 함께 구매할 가능성이 높은지 분석할 수 있다.这样하면 마케팅 계획을 수립할 때 고객의 покуп기 행동을 예측하고 타겟 마케팅을 수행할 수 있다. 다른 옵션인 군집 분석, 회귀 분석, 분류 분석은 다른 목적의 데이터 분석에 더 적절하다. 군집 분석은 유사한 특성을 가진 데이터를 군집화하는 데 사용되고, 회귀 분석은 연속적인 값을 예측하는 데 사용되며, 분류 분석은 категор리 값을 예측하는 데 사용된다. 따라서 카달로그 배열, 교차 판매 등의 마케팅 계획을 수립할 때는 연관규칙 학습이 가장 적절한 데이터 마이닝 기법이다.</p>"]},"rate":73,"rateN":2892},{"id":"62108","number":24,"category":"데이터 분석","type":"choice","subject":"앙상블 설명으로 옳은 것은?","choices":[{"n":1,"html":"대표적인 기법으로 배깅과 부스팅이 있다."},{"n":2,"html":"Voting은 서로 같은 여러개의 알고리즘을 사용한다"},{"n":3,"html":"Hard Voting은 확률의 평균을 구해 높은 것을 선택한다."},{"n":4,"html":"Random Forest는 대표적인 부스팅 방식이다."}],"answer":[1],"explain":{"ai":["<p>앙상블은 여러 개의 모델을 결합하여 하나의 강력한 모델을 만드는 방법입니다. 앙상블의 대표적인 기법으로 배깅과 부스팅이 있습니다. 배깅은 같은 알고리즘을 여러 번 사용하여 예측 결과를 결합하는 방법이며, 부스팅은 약한 모델을 여러 개 결합하여 강한 모델을 만드는 방법입니다. 따라서 앙상블의 대표적인 기법으로 배깅과 부스팅이 있다는 설명은 옳습니다. </p>\n<p>他の 설명은 옳지 않습니다. Voting은 서로 다른 알고리즘을 사용하여 결과를 결합하는 방법이며, Hard Voting은 각 알고리즘의 예측 결과 중에서 가장 많이 나온 클래스를 선택하는 방법입니다. Random Forest는 대표적인 배깅 방식이며, 여러 개의 의사결정나무 모델을 결합하여 예측하는 방법입니다.</p>"]},"rate":72,"rateN":2844},{"id":"62109","number":25,"category":"데이터 분석","type":"choice","subject":"apriori 알고리즘의 분석 절차로 맞는 것은?","extra":"<pre class=\"contents\">가) 최소 지지도를 설정한다.\r\n나) 개별 품목들 중에서 최소 지지도를 넘는 모든 품목들을 찾는다.\r\n다) 이전 단계에서 찾은 개별 품목만을 이용하여 최소 지지도를 넘는 두 가지 품목을 찾는다.\r\n라) 이전 단계에서 찾은 품목의 집합을 결합하여 최소 지지도를 세가지 품목의 집합을 찾는다.\r\n마) 반복적으로 수행하여 최소 지지도가 넘는 반발 품목을 찾는다.</pre>","choices":[{"n":1,"html":"가 - 마 - 다 - 나 - 라"},{"n":2,"html":"가 - 나 - 다 - 라 - 마"},{"n":3,"html":"가 - 마 - 라 - 나 - 다"},{"n":4,"html":"나 - 가 - 다 - 마 - 라"}],"answer":[2],"explain":{"ai":["<p>apriori 알고리즘은 자주 발생하는 품목 집합을 찾는 알고리즘이다. 분석 절차는 다음과 같다. </p>\n<p>최소 지지도를 설정하고, 개별 품목들 중에서 최소 지지도를 넘는 모든 품목들을 찾는 것이다. \n이후에는 이전 단계에서 찾은 개별 품목만을 이용하여 최소 지지도를 넘는 두 가지 품목을 찾는다. \n그다음 이전 단계에서 찾은 품목의 집합을 결합하여 최소 지지도를 넘는 세가지 품목의 집합을 찾는 것이다. \n마지막으로 반복적으로 수행하여 최소 지지도가 넘는 반복 품목을 찾는 것이다. \n즉, 분석 절차는 최소 지지도 설정, 개별 품목 찾기, 두 가지 품목 찾기, 세 가지 품목 찾기, 반복적으로 품목 찾기로进行된다. \n따라서 정답은 2번, 가 - 나 - 다 - 라 - 마이다.</p>"]},"rate":82,"rateN":2521},{"id":"62110","number":26,"category":"데이터 분석","type":"choice","subject":"다음 오분류표를 사용하여 재현율을 구한 결과는 무엇인가?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"0.15"},{"n":2,"html":"0.3"},{"n":3,"html":"0.4"},{"n":4,"html":"0.55"}],"answer":[3],"rate":85,"rateN":2331},{"id":"62130","number":26,"category":"데이터 분석","type":"short","subject":"여러 개의 앙상블 모형 중 붓스트랩 표본을 구성하는 재표본 과정에서 분류가 잘못된 데이터에 더 큰 가중치를 주어 표본을 추출하는 기법은?","shortAnswer":"부스팅","explain":{"ai":["<p>부스팅은 앙상블 학습 기법 중 하나로, 기존 모델의 오류를 집중적으로 개선하는 방식을 취합니다. 특히 문제에서 언급한 특징, 즉 이전 모델에서 분류가 잘못된 데이터에 더 큰 가중치를 부여하여 새로운 학습 표본을 만드는 과정이 핵심입니다. 이렇게 하면 모델이 반복적으로 과거 오류를 학습하고 개선하며, 성능을 점진적으로 높이는 효과를 얻습니다. 이는 랜덤 포레스트와 같은 다른 앙상블 방법과 구분되는 주요 특징으로, 부스팅 알고리즘들이 (예: AdaBoost, Gradient Boosting) 이러한 재표본화 전략을 통해 강력한 예측력을 발휘합니다. 따라서 올바른 답은 부스팅입니다.</p>"]}},{"id":"62111","number":27,"category":"데이터 분석","type":"choice","subject":"다음 연관 규칙에 대한 설명 중 잘못된 것은?","choices":[{"n":1,"html":"비목적성 분석 기법으로 계산이 간편하다"},{"n":2,"html":"대표적인 알고리즘으로 Aprior가 있다."},{"n":3,"html":"조건 반응으로 표현되는 연관분석의 결과를 이해하기 쉽다."},{"n":4,"html":"분석 품목 수가 증가해도 계산은 복잡해지지 않는다."}],"answer":[4],"explain":{"ai":["<p>연관 규칙은 데이터 마이닝에서 사용되는 비목적성 분석 기법 중 하나로, 데이터 간의 연관성이나 규칙성을 발견하는 데 사용된다. 일반적으로 계산이 간단하고 이해하기 쉽다. 대표적인 알고리즘으로는 Apriori가 있다. </p>\n<p>연관 규칙의 결과는 조건과 반응으로 표현되는데, 이는 분석 결과를 이해하기 쉽게 한다. 하지만 분석 대상이 되는 품목 수가 증가하면 계산량이 기하급수적으로 증가하기 때문에 복잡해진다. 따라서 분석 품목 수가 증가해도 계산이 복잡해지지 않는다는 설명은 잘못되었다.</p>"]},"rate":84,"rateN":2438},{"id":"62112","number":28,"category":"데이터 분석","type":"choice","subject":"잔차의 정규성 검토에 대한 설명 중 옳지 않은 것은?","choices":[{"n":1,"html":"Q-Q plot으로 대략적인 확인이 가능하다."},{"n":2,"html":"잔차의 히스토그램이나 산점도를 그려서 정규성 문제를 검토하기도 한다."},{"n":3,"html":"정규성을 검정하는 방법으로 Shapiro-Wilk test, Anderson-darling test등을 이용할 수 있다."},{"n":4,"html":"정규성을 만족하지 못할 때 상관계수가 가장 큰 값을 제거한다."}],"answer":[4],"explain":{"ai":["<p>정규성 검토는 데이터 분석의 중요한 부분입니다. 잔차의 정규성을 확인하는 방법에는 여러 가지가 있으며, Q-Q plot, 히스토그램, 산점도 등을 사용할 수 있습니다. Shapiro-Wilk test나 Anderson-darling test와 같은 통계적 검정 방법도 이용할 수 있습니다. 그러나 정규성이 만족하지 못할 때 상관계수가 가장 큰 값을 제거하는 것은 올바른 방법이 아닙니다. 이는 데이터의 일부를 임의로 제거하는 것으로, 분석 결과에 영향을 줄 수 있습니다. 올바른 방법은 데이터의 전처리나 변환을 통해 정규성을 개선하거나, 비PARAMETRIC 통계기법 등을 사용하는 것입니다. 따라서 4번이 옳지 않은 설명입니다.</p>"]},"rate":79,"rateN":2584},{"id":"62113","number":29,"category":"데이터 분석","type":"choice","subject":"777개 대학을 대상으로 졸업률이 비용과 관련 있는가를 회귀 분석한 결과이다.\r\n잘못 해석한 것은 무엇인가? 등록금(Outstate), 기숙사 비용(Room.board), 개인비용지출(Personal)","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"등록금이 높아지면 졸업률이 높아진다"},{"n":2,"html":"개인비용지출이 노파지면 졸업률이 낮아진다."},{"n":3,"html":"비용과 졸업률 사이의 인과관계를 확인 할 수 있다."},{"n":4,"html":"모든 변수의 회귀 계수는 유의미하다."}],"answer":[3],"rate":55,"rateN":3098},{"id":"62114","number":30,"category":"데이터 분석","type":"choice","subject":"의사결정 나무에 대한 설명 중 적절하지 않은 것은?","choices":[{"n":1,"html":"비지도 학습으로 상향식 접근 방법을 이용한다."},{"n":2,"html":"구조가 단순하여 해석이 용이하다"},{"n":3,"html":"목표 변수가 이산형인 경우 분류나무, 목표변수가 연속형인 경우 회귀나무가 있다."},{"n":4,"html":"부모마디보다 자식마디의 순수도가 증가하도록 분류나무를 형성해 나간다."}],"answer":[1],"explain":{"ai":["<p>정답은 1번입니다. 의사결정 나무는 주로 지도 학습의 범주에 속하며, 상향식(자율적 클러스터링)이 아닌 하향식(지도된 레이블 기반 분류) 접근 방법을 취합니다. 비지도 학습은 데이터 내의 내재된 패턴이나 구조를 스스로 발견하는 방식으로, 의사결정 나무의 학습 방식과는 맞지 않습니다. 반면, 나머지 옵션들은 의사결정 나무의 특징을 정확히 설명하고 있습니다:</p>\n<ul>\n<li>2번: 의사결정 나무의 구조가 직관적이고 이해하기 쉬운 점을 잘 나타내고 있습니다.</li>\n<li>3번: 목표 변수의 종류에 따라 분류나무와 회귀나무로 구분되는 사실을 정확히 설명합니다.</li>\n<li>4번: 의사결정 나무가 각 단계에서 정보 이득이나 지니 계수 등을 통해 자식 노드의 순수도를 높이는 방향으로 분기한다는 점을 잘 표현하고 있습니다.</li>\n</ul>"]},"rate":66,"rateN":2989},{"id":"62115","number":31,"category":"데이터 분석","type":"choice","subject":"아래 인공 신경망 활성 함수는 무엇인가?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"부호함수"},{"n":2,"html":"계단함수"},{"n":3,"html":"시그모이드"},{"n":4,"html":"소프트맥스"}],"answer":[3],"rate":75,"rateN":2734},{"id":"62116","number":32,"category":"데이터 분석","type":"choice","subject":"모수의 새로운 가설을 옳다고 판단할 수 있는지 표본 통계량 평가 판단과정을 설명하는 용어 중 적절한 것은?","choices":[{"n":1,"html":"점추정"},{"n":2,"html":"구간추정"},{"n":3,"html":"가설검정"},{"n":4,"html":"연구가설"}],"answer":[3],"wiki":[{"title":"귀무가설","url":"https://itwiki.kr/w/귀무가설"}],"explain":{"ai":["<p>해설은 이렇게 한다. \n모수의 새로운 가설을 옳다고 판단할 수 있는지 평가하는 과정은 가설검정이라 불린다. \ngà설검정은 연구자가 설정한 가설이 옳은지 틀린지를 확인해주는 통계적 기법이다. \n연구자는 가설을 설정한 후에 표본을 통해서 가설의 적합도를 평가한다.\n여기서 표본 통계량은 표본으로 부터atever 계산된 통계값을 말한다. \ngà설검정의 결과는atever 연구자가 설정한 가설이 기각될 수도 있고 채택될 수도 있다. \n이처럼 가설의 옳고 그름을 평가하고 판단하는 과정을 가설검정이라고 한다.\n따라서 정답은 가설검정이다.</p>"]},"rate":84,"rateN":2552},{"id":"62117","number":33,"category":"데이터 분석","type":"choice","subject":"ROC Curve의 이상적 완벽 분류모형의 X축과 Y축 가장 적절한 것은? 단(X값, Y값)","choices":[{"n":1,"html":"(0,0)"},{"n":2,"html":"(0,1)"},{"n":3,"html":"(1,0)"},{"n":4,"html":"(1,1)"}],"answer":[2],"explain":{"ai":["<p>ROC Curve는 분류 모델의 성능을 평가하는 그래프입니다. 이상적인 완벽 분류 모형은 모든 양성 샘플을 올바르게 분류하고, 모든 음성 샘플을 올바르게 분류합니다. </p>\n<p>X축은 거짓 양성률(false positive rate)을 나타내고, Y축은 진양성률(true positive rate)을 나타냅니다. 이상적인 분류 모형에서는 거짓 양성률이 0이고 진양성률이 1입니다. 즉, 하나도 틀리지 않고 모든 실제 양성 데이터를 모두 올바르게 분류합니다. </p>\n<p>따라서 이상적인 완벽 분류 모형의 ROC Curve는 (0,1) 지점에서 시작합니다.[cnt] </p>\n<p>이러한 이유로 ROC Curve의 이상적 완벽 분류모형의 X축과 Y축 가장 적절한 값은 (0,1)입니다.</p>"]},"rate":62,"rateN":3130},{"id":"62118","number":34,"category":"데이터 분석","type":"choice","subject":"회귀분석 설명 중 가장 적절하지 못한 것은?","choices":[{"n":1,"html":"독립변수와 종속변수의 인과관계가 중요하다."},{"n":2,"html":"성별과 같이 두 집단으로 분류된 명목형 자료여도, 회귀분석에서 독립변수로 사용할 수 있다."},{"n":3,"html":"잔차와 독립변수 간의 상관관계가 없다."},{"n":4,"html":"결정계수는 독립변수가 종속변수의 분산을 설명할 수 있는 정도를 나타낸다."}],"answer":[1],"explain":{"ai":["<p>정답은 1번입니다. 회귀분석에서 독립변수와 종속변수 간의 관계는 상관관계를 통해 설명되며, 반드시 인과관계를 요구하지 않습니다. 인과관계를 가정하는 것은 분석의 한계를 지니며, 실제 데이터 분석에서는 관찰된 상관관계만을 기반으로 하는 경우가 많습니다. 따라서 \"독립변수와 종속변수의 인과관계가 중요하다\"는 설명은 회귀분석의 핵심 원리와 가장 적절하지 않습니다. 다른 보기들은 각각 회귀분석의 올바른 특징을 잘 나타내고 있습니다: 명목형 변수의 사용 가능성 (단, 적절한 변환이나 모델 선택 필요), 잔차의 독립성, 결정계수의 의미 등이 제대로 설명되어 있습니다.</p>"]},"rate":42,"rateN":4279},{"id":"62119","number":35,"category":"데이터 분석","type":"choice","subject":"주성분 분석의 내용 중 가장 적절하지 않은 것은?","choices":[{"n":1,"html":"회귀분석의 다중공선성 문제 해결을 위해 사용한다."},{"n":2,"html":"서로 상관성이 높은 변수를 선형 결합하여 변수를 축소, 해석상 구조적 문제해결을 위해 사용한다."},{"n":3,"html":"다변량 데이터의 저 차원 그래프 표시 및 이상치 탐색에 사용한다."},{"n":4,"html":"원래 변수를 선형결합 할 때 목표변수를 고려할 필요는 없다."}],"answer":[4],"explain":{"ai":["<p>주성분 분석은 데이터의 차원을 줄이고 변수 간의 상관관계를 파악하는 데 사용한다. 주성분 분석의 주요 내용은 다음과 같다. </p>\n<p>첫째, 다중공선성 문제 해결을 위해 사용한다. 주성분 분석은 변수 간의 상관관계가 높은 경우에 사용하여 회귀분석의 다중공선성 문제를 해결하는 데 도움을 준다. </p>\n<p>둘째, 서로 상관성이 높은 변수를 선형 결합하여 변수를 축소하고, 해석상 구조적 문제 해결을 위해 사용한다. 주성분 분석은 상관성이 높은 변수를 선형 결합하여 변수의 수를 줄이고, 데이터의 구조를 더 잘 이해하는 데 도움이 된다. </p>\n<p>셋째, 다변량 데이터의 저 차원 그래프 표시 및 이상치 탐색에 사용한다. 주성분 분석은 데이터를 저 차원으로 환원하여 그래프를 표시하고, 이상치를 탐색하는 데 사용할 수 있다. </p>\n<p>하지만 주성분 분석은 원래 변수를 선형 결합할 때 목표 변수를 고려할 필요가 있다. 주성분 분석은 변수의 상관관계를 파악하는 데 사용되며, 목표 변수를 고려하지 않으면 분석의 결과가 왜곡될 수 있다. </p>\n<p>따라서 주성분 분석의 내용 중 가장 적절하지 않은 것은 원래 변수를 선형 결합 할 때 목표 변수를 고려할 필요는 없다라는 주장이다.</p>"]},"rate":77,"rateN":2655},{"id":"62120","number":36,"category":"데이터 분석","type":"choice","subject":"시계열 모형에서 ARIMA에 대한 설명으로 옳은 것은?","choices":[{"n":1,"html":"ARIMA는 Auto- Regressive Improved Moving Average의 약자이다."},{"n":2,"html":"ARIMA(p, d, q)에서 p가 0이면 IMA(d, q)모형이다."},{"n":3,"html":"AR은 이동평균, MA는 자기회귀 모형이다."},{"n":4,"html":"ARIMA는 정상시계열 모형이다."}],"answer":[2],"explain":{"ai":["<p>ARIMA 모형은 시계열 분석에서 많이 사용되는 통계 모형 중 하나이다. 이 모형은 시계열 데이터가 자기회귀 selfieenger와 이동평균 성분을 모두 포함할 수 있는 모형이다. </p>\n<p>ARIMA(p,d,q)에서 p는 자기회귀 성분의 차수, d는 차분의 차수, q는 이동평균 성분의 차수를 나타낸다. </p>\n<p>ARIMA 모형 중에 p가 0이면 자기회귀 성분이 없다는 뜻이므로 IMA(d,q) 모형이다. 다시 말해서 p가 0일 때는 d차의 차분을 수행하고 q차의 이동평균 성분만_model로 사용한다는 것이다. </p>\n<p>정상 시계열이란 평균과 분산이 시간의 함수로 변하지 않고 상관계수는 시간의 함수로 변하지 않는 시계열을 의미한다. 그러나 이러한 정상 시계열에 대해서 ARIMA 모형을 적용할 때는 d차의 차분 과정을 통해 시계열이 정상 시계열이 되도록 하는 것이 일반적이다. </p>\n<p>AR은 자기회귀 모형을 의미하고 MA는 이동평균 모형을 의미한다.</p>"]},"rate":59,"rateN":3232},{"id":"62121","number":37,"category":"데이터 분석","type":"choice","subject":"다음 설명에 해당되는 앙상블 기법은?","extra":"<pre class=\"contents\">여러 개의 붓스트랩 자료를 생성하고 각 붓스트랩 자료에 예측 모형을 만든 후 결합하여 최종 예측 모형을 만드는 방법이다.</pre>","choices":[{"n":1,"html":"배깅(bagging)"},{"n":2,"html":"부스팅(boosting)"},{"n":3,"html":"Voting"},{"n":4,"html":"Stacking"}],"answer":[1],"explain":{"ai":["<p>붓스트랩 자료는 원래의 데이터셋에서 랜덤하게 샘플링하여 생성한 복제본을 뜻한다. 이 설명에 해당되는 앙상블 기법을 찾으면 된다. 배깅은 여러 개의 붓스트랩 자료를 생성하고 각 자료에 예측 모형을 만든 후 예측 결과를 결합하여 최종 예측 모형을 생성하는 것이다. 이에 반해 부스팅은 순차적으로 예측 모형을 생성하며 이전 모형의 오차를 보완하는 방식이다. 보팅은 여러 예측 모형의 예측 결과를 결합하여 최종 예측을 하는 방식이며 스택킹은 여러 예측 모형의 예측 결과를 다시 하나의 예측 모형으로 결합하는 방식이다. 따라서 주어진 설명에 해당되는 앙상블 기법은 배깅이기 때문에 정답은 1번이다.</p>"]},"rate":72,"rateN":2870},{"id":"62122","number":38,"category":"데이터 분석","type":"choice","subject":"시계열 데이터의 정상성 관련 내용으로 틀린 것은?","choices":[{"n":1,"html":"모든 시점에 대해 일정한 평균을 가진다."},{"n":2,"html":"공분산은 단지 시차에만 의존하고 시점 자체에는 의존하지 않는다."},{"n":3,"html":"모든 시점에 대해 일정한 분산을 가진다."},{"n":4,"html":"지수평활법은 최근 데이터를 이용하여 미래를 예측하는 방법이다."}],"answer":[4],"explain":{"ai":["<p>시계열 데이터의 정상성은 평균과 분산이 시간에 따라 일정하며 공분산이 시차에만 의존한다는 것을 의미한다. 따라서 정상성을 만족하는 조건은 평균과 분산이 일정하고 공분산이 시차에만 의존하는 것이다. </p>\n<p>지수 평활법은 과거의 데이터를 이용해 현재와 미래를 예측하는 방법으로 시계열 데이터의 최근趨勢를 반영하여 예측하는 데 사용된다. 그러나 지수 평활법이 최근 데이터만을 이용하여 미래를 예측한다는 것은 정확하지 않다. 지수 평활법은 과거 데이터의 가중 평균이며 가중치를 통해 최근 데이터에 더 높은 가중치를 줄 수도 있다. </p>\n<p>따라서 4번이 틀린 것이다. 또한 1번과 3번은 정상성의 조건에 해당하고 2번은 정상성의 정의에 해당한다.</p>"]},"rate":52,"rateN":3694},{"id":"62123","number":39,"category":"데이터 분석","type":"choice","subject":"다음 64개 변수에 대한 주성분 분석의 Scree plot결과에 대한 해석으로 틀린 것은?","extra":"<pre class=\"contents\">점 64개 1번째 점이 0.12에 근접, 2번째 점이 0.07에 근접, 7,8번째에서 기울기 감소, 나머지 60까지 점은 밀집되게 나열</pre>","choices":[{"n":1,"html":"첫번째 주성분으로 10%이상 설명이 가능하다."},{"n":2,"html":"주성분 64개로 100% 분산을 설명 할 수 있다"},{"n":3,"html":"두 개의 주성분으로 7% 분산을 설명한다"},{"n":4,"html":"7, 8번째 성분에서부터 완만한 기울기를 가진다."}],"answer":[3],"explain":{"ai":["<p>해설:\nScree plot은 각 주성분의 설명력 감소 추세를 보여주는 그래프다. 주어진 결과에서:</p>\n<ul>\n<li>1번 주성분이 0.12로 가장 높은 척을 차지하여, 전체 분산의 약 10% 이상을 설명할 수 있다는 1번 보기는 맞다.</li>\n<li>모든 주성분을 포함하면 이론적으로 100% 분산 설명이 가능하다는 점에서 2번도 사실이다.</li>\n<li>7, 8번째 주성분에서 기울기가 감소하기 시작하고 이후 점들이 밀집되는 패턴은 4번 보기와 일치한다.</li>\n<li>그러나 3번 보기는 두 개의 주성분으로 겨우 0.2% (0.12 + 0.07)의 분산만 설명할 수 있다는 것을 의미하며, 문제에서 제시된 7% 분산 설명은 과도한 해석이다. 실제 데이터에서는 이 정도 비율을 달성하기 어렵다.</li>\n</ul>\n<p>따라서, 틀린 해석은 3번이다.</p>"]},"rate":57,"rateN":2988},{"id":"62124","number":40,"category":"데이터 분석","type":"choice","subject":"kNN에 대한 설명으로 틀린 것은?","choices":[{"n":1,"html":"인스턴스 러닝기법이다."},{"n":2,"html":"K값이 클수록 과대적합(Overfitting)문제가 발생한다."},{"n":3,"html":"가까운 것으로 군집하는 것이다."},{"n":4,"html":"K는 가까운 이웃의 개수를 의미한다."}],"answer":[2],"explain":{"ai":["<p>kNN은 근접 이웃 알고리즘이며 인스턴스 러닝 기법이다. 이는 데이터를 미리 학습하지 않기 때문에 새로운 데이터가 들어왔을 때Toe最近의 k개의 데이터와의 거리를 계산하여 분류 또는 회귀를 수행한다. 가까운 것으로 군집하는 것이므로 3번은 정답이 아님. k는 가까운 이웃의 개수를 의미하므로 4번도 정답이 아님. k값이 클수록 과소적합(Underfitting) 문제가 발생한다. k값이 작을수록 과대적합(Overfitting) 문제가 발생한다. 이것은 k가 커질수록 많은 데이터가 고려되기 때문이다. 따라서 2번은 틀린 설명이다.</p>"]},"rate":53,"rateN":3460},{"id":"62125","number":41,"category":"데이터 분석","type":"choice","subject":"Credit 데이터는 400명의 신용카드 고객에 대한 신용카드와 관련된 변수들이 포함되어 있다. 아래 변수 간의 산점도와 피어슨 상관계수를 나타내고 있다. 그림에 대한 설명 중 가장 부적절 한 것은?","extra":"<img src=\"data:image/png;base64,\" style=\"padding:10px 18px; max-width:100%\">","choices":[{"n":1,"html":"가장 상관관계가 높은 두 변수는 Limit와 Balance이다."},{"n":2,"html":"모든 상관관계가 양의 상관관계를 보인다."},{"n":3,"html":"Balance와 가장 상관관계가 높은 변수는 Income이다."},{"n":4,"html":"Age와 Balance는 매우 낮은 상관관계를 보인다."}],"answer":[3],"rate":60,"rateN":2639},{"id":"62126","number":42,"category":"데이터 분석","type":"choice","subject":"군집 분석에 대한 설명으로 잘못된 것은?","choices":[{"n":1,"html":"형성된 군집에 대해 논리성보다 안정성이 더 중요하다."},{"n":2,"html":"비지도학습으로 군집간 분산 최대화, 군집내 분산을 최소화 한다."},{"n":3,"html":"집단별 특성이 유사할 경우 안정성이 높을 수 있다."},{"n":4,"html":"유사성을 이용하여 몇 개의 집단으로 그룹화하는 분석이다."}],"answer":[1],"explain":{"ai":["<p>1번이 잘못된 설명입니다. 군집 분석에서 논리성과 안정성은 모두 중요한 요소입니다.  안정성이 높은 군집은 데이터의 작은 변화에 덜 민감하게 반응하지만, 논리적 의미와 실제 해석 가능성도 무시할 수 없습니다. 군집 내의 데이터가 실제 의미론적으로 연결되어 있고, 분석 목적에 부합하는지 평가하는 논리성이 필수적입니다. 따라서 논리성보다 안정성만을 우선시하는 것은 부적절합니다. </p>\n<p>2번은 올바른 설명으로, 군집 분석이 군집 간의 차이를 최대화하고 군집 내의 유사성을 최소화하는 비지도 학습 방법임을 잘 나타냅니다. \n3번 또한 정확하며, 유사한 특성을 가진 데이터가 같은 군집에 속할 때 군집의 안정성이 높아질 수 있음을 의미합니다.\n4번은 군집 분석의 기본 개념을 명확히 설명하고 있어 올바른 설명입니다.</p>"]},"rate":57,"rateN":3289},{"id":"62127","number":43,"category":"데이터 분석","type":"choice","subject":"회귀 모형을 평가하는 방법으로 옳지 않은 것은?","choices":[{"n":1,"html":"모형이 통계적으로 유의미한가?"},{"n":2,"html":"모형이 데이터를 잘 적합하는가?"},{"n":3,"html":"회귀계수가 유의한가?"},{"n":4,"html":"선형성, 정상성, 독립성을 만족하는가?"}],"answer":[4],"explain":{"ai":["<p>회귀 모형 평가에는 통계적 유의성과 데이터 적합 度 그리고 회귀계수의 유의성 등이 포함된다. 그러나 선형성, 정상성, 독립성은 회귀분석의 가정이기 때문에 이를 만족하는지 확인하는 것은 回귀 모형의 전제 조건이 맞는지 체크하는 것이다. 따라서 회귀 모형을 평가하는 방법으로는 옳지 않다. 즉, 선형성, 정상성, 독립성은 회귀 모형을 구축하기 전에 사전에 만족하는지 확인해야 하는 조건이므로 평가 방법이 아니다.</p>"]},"rate":54,"rateN":3312},{"id":"62128","number":44,"category":"데이터 분석","type":"choice","subject":"상관분석에 대한 설명으로 옳은 것은?","choices":[{"n":1,"html":"스피어만 상관계수는 선형관계 파악만 가능하다."},{"n":2,"html":"피어슨 상관계수는 서열척도에서 사용한다."},{"n":3,"html":"피어슨 상관계수가 0이면 상관관계가 없다."},{"n":4,"html":"공분산은 측정 단위에 영향을 받지 않는다."}],"answer":[3],"explain":{"ai":["<p>상관분석은 두 변수 간의 관련성을 분석하는 통계기법입니다. 피어슨 상관계수는 두 변수 간의 선형 상관관계를 측정하며, 이 값이 0에 가까울수록 두 변수 간의 상관관계가 없습니다. 따라서 피어슨 상관계수가 0이면 상관관계가 없다는 것은 옳은 설명입니다.</p>\n<p>스피어만 상관계수는 순위 상관계수로서 비선형 상관관계도 측정 가능합니다. 피어슨 상관계수는 등간척도나 비율척도에서 주로 사용되며, 서열척도에서는 스피어만 상관계수를 사용합니다. 공분산은 측정 단위에 영향을 받으므로 표준화된 값인 상관계수를 사용하여 상관관계를分析합니다. 따라서 다른 설명은 옳지 않습니다.</p>"]},"rate":60,"rateN":3283},{"id":"62129","number":45,"category":"데이터 분석","type":"short","subject":"데이터 집합으로부터 크기가 같은 표본을 여러 번 단순 임의 복원 추출하여 각 표본에 대해 분류기를 생성한 후 그 결과를 앙상블 하는 방법으로 노드 내 데이터를 자식 노드로 나누는 기준을 정할 때 설명변수의 일부분만을 고려함으로 성능을 높이는 방법을 사용하는 것을 무엇이라 하는가?","shortAnswer":"랜덤 포레스트","explain":{"ai":["<p>이 방법은 랜덤 포레스트라고 불린다. 랜덤 포레스트는 여러개의 의사결정나무를 랜덤하게 생성하여 앙상블하는 기법이다. 각 의사결정나무는 전체 설명변수 중 일부분만을 고려하여 노드를 분할한다. 이렇게 생성된 여러개의 의사결정나무의 결과를 결합하여 최종 결과를 도출한다. 랜덤 포레스트는 과적합을 방지하고 예측 성능을 향상시키는 데에 효과적이다.</p>"]}},{"id":"62131","number":47,"category":"데이터 분석","type":"short","subject":"다음이 설명하는 것은 무엇인가?","extra":"<pre class=\"contents\">클러스터 안의 데이터들이 다른 클러스터와 비교해 얼마나 비슷한가를 나타내는 군집분석 타당성 평가지표로 1에 가까울수록 군집화가 잘 되었다고 판단한다.</pre>","shortAnswer":"실루엣 계수","explain":{"ai":["<p>클러스터 안의 데이터들이 다른 클러스터와 비교해 얼마나 비슷한가를 나타내는 군집분석 타당성 평가지표는 실루엣 계수다. 이 지표는 1에 가까울수록 군집화가 잘 되었다고 판단한다. 이는 클러스터 내의 데이터는 서로 비슷하고 다른 클러스터와는 다르다는 것을 의미한다. 실루엣 계수는 클러스터링 알고리즘의 성능을 평가하는 데 사용되며, 클러스터링 결과의 품질을 측정하는 중요한 지표 중 하나다.</p>"]}},{"id":"62132","number":48,"category":"데이터 분석","type":"short","subject":"인공신경망 관련 알고리즘 중 다음 설명은 어떤 것을 말하는가?","extra":"<pre class=\"contents\">지도 학습에서 신경망을 학습 시키는 방법으로, 출력층에서 제시한 값에 대해, 실제 원하는 값으로 학습하는 방법으로 사용되고, 동일 입력층에 대해 원하는 값이 출력되도록 개개의 weight를 조정하는 방법으로 사용되는 알고리즘이다.</pre>","shortAnswer":"역전파 알고리즘","explain":{"ai":["<p>인공신경망의 학습 방법 중 하나로, 출력층과 실제 원하는 값의 차이를.exam으로 하여, 이 오차를 줄이는 방향으로 weight를 조정하는 알고리즘이다.(outputs에 대한 오차를 줄이는 것이라고 보면 됨). 신경망의 학습에서 중요한 역할을 하는 알고리즘이며, 오차를 최소화 하여 모델의 성능을 높이는 데 사용된다. 식별된 알고리즘은 신경망의 학습에서 매우 중요하며, 많은 응용 분야에서 사용된다.</p>"]}},{"id":"62133","number":49,"category":"데이터 분석","type":"short","subject":"모집단에서 표본을 추출하여 모집단의 모수를 추측하는 과정에서 범위가 아니라 가장 참값이라고 여겨지는 하나의 모수를 택하는 것을 무엇이라고 하는가?","shortAnswer":"점추정","explain":{"ai":["<p>모집단의 특성을 파악하기 위해 표본을 추출하고 분석한다. 이때 모집단의 모수를 추측하는 방법은점추정과 구간추정으로 나뉜다. 점추정은 모집단의 모수에 대해 가장 가능성이 높은 하나의 값을 추정하는 것이다. 이는 모집단의 평균이나 분산과 같은 특성을 한 가지 특정 값으로 추정하는 것을 의미한다. 점추정은 간단하고 직관적이지만, 추정값이 항상 실제 모수와 정확히 일치하지는 않기 때문에 오차가 있을 수 있다.</p>"]}},{"id":"62134","number":50,"category":"데이터 분석","type":"short","subject":"CART에서 쓰이는 불순도 측정 지표로 데이터의 통계적 분산 정도를 정량화해서 표현한 값은 무엇인가","shortAnswer":"지니 지수 / 지니 계수","explain":{"ai":["<p>CART에서 사용되는 불순도 측정 지표 중 하나는 지니 지수 또는 지니 계수입니다. 이 지표는 데이터의 통계적 분산 정도를 정량화해서 표현한 값입니다. 지니 지수는 데이터셋이 얼마나 퍼져 있는지 보여주는 측정 지표로, 데이터셋의 분산 정도를 산출합니다. 지니 계수는 0에서 1 사이의 값을 가지며, 값이 높을수록 데이터의 분산 정도가 크다는 것을 나타냅니다. CART 알고리즘에서 지니 지수는 불순도 측정 지표 중 하나로 사용되어 노드 분할 시 가장 좋은 특성을 선택하기 위해 사용됩니다.</p>"]}}]};